/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base SYR2K kernel closely following the PolyBench formulation.
# We operate only on the lower triangle (j <= i).
@proc
def syr2k_base(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
    B: DATA_TYPE[n, m] @ DRAM,
):
    # Load scalar parameters once into local temporaries to avoid
    # repeatedly dereferencing scalar arguments in the inner loops.
    alpha0: DATA_TYPE
    beta0: DATA_TYPE
    alpha0 = alpha
    beta0 = beta

    # First scale the lower triangle of C by beta.
    # This pass is independent of the update and touches each C[i, j] once.
    for i in seq(0, n):
        for j in seq(0, i + 1):
            C[i, j] = beta0 * C[i, j]

    # Then apply the symmetric rank-2k update on the lower triangle.
    # This matches the original Exo kernel semantics:
    #   C[i, j] += alpha * (A[j, k] * B[i, k] + B[j, k] * A[i, k])
    # but factored to reduce the number of multiplications by alpha.
    for i in seq(0, n):
        for k in seq(0, m):
            for j in seq(0, i + 1):
                C[i, j] += alpha0 * (
                    A[j, k] * B[i, k] + B[j, k] * A[i, k]
                )

# -----------------------------
# Scheduling / optimization
# -----------------------------

# 1. Improve memory locality for A and B by interchanging k and j
#    in the update nest:  for i, k, j  ->  for i, j, k
#    This makes accesses A[j, k] and B[j, k] traverse k contiguously.
k_loop = syr2k_base.find_loop("k")
syr2k_opt = reorder_loops(syr2k_base, k_loop)

# 2. Fuse the two outer i loops (scaling and update passes).
#    This preserves per-(i, j) ordering but improves cache reuse on C.
i_loop_0 = syr2k_opt.find_loop("i #0")
i_loop_1 = syr2k_opt.find_loop("i #1")
syr2k_opt = fuse(syr2k_opt, i_loop_0, i_loop_1)

# 3. Inside each i-loop, fuse the two j-loops so that scaling of C[i, j]
#    is immediately followed by its rank-2k update.
j_loop_0 = syr2k_opt.find_loop("j #0")
j_loop_1 = syr2k_opt.find_loop("j #1")
syr2k_opt = fuse(syr2k_opt, j_loop_0, j_loop_1)

# 4. Tile the k dimension to improve cache behavior on the long reduction.
#    TILE_K is a compile-time constant that can be tuned.
TILE_K = 32
k_inner = syr2k_opt.find_loop("k")
syr2k_opt = divide_loop(syr2k_opt, k_inner, TILE_K, ["ko", "ki"], tail="guard")

# 5. Parallelize the outermost i-loop. Each i-iteration updates a distinct
#    row of C and is therefore independent.
i_outer = syr2k_opt.find_loop("i")
syr2k_opt = parallelize_loop(syr2k_opt, i_outer)

# 6. Perform some algebraic and control-flow simplifications on the result.
syr2k_opt = simplify(syr2k_opt)

# 7. Expose the scheduled kernel under the name expected by the C driver.
kernel_syr2k = rename(syr2k_opt, "kernel_syr2k")

